describe("extraUnsealPasswords", () => {
  const password = sessionConfig.password;
  const oldA = "old-password-a-0123456789012345678901";
  const oldB = "old-password-b-0123456789012345678901";
  const unknownX = "unknown-password-x-0123456789012345";
  const createdAt = 1_700_000_000_000;

  const tokenOf = (setCookie: string) =>
    decodeURIComponent(setCookie.match(/h3-test=([^;]+)/)![1]);
  const sessionCookie = (res: Response) =>
    res.headers.getSetCookie().find((c) => c.startsWith("h3-test="))!;
  const sealedWith = (sealPassword: string, data: Record<string, any> = { user: "ana" }) =>
    seal({ id: "s1", createdAt, data }, sealPassword, sealDefaults);
  const readRoute = (path: string, config: SessionConfig) => {
    t.app.get(path, async (event) => {
      const session = await getSession(event, config);
      return { id: session.id, createdAt: session.createdAt, data: session.data };
    });
  };

  it("seals the same way with extraUnsealPasswords absent or empty", async () => {
    t.app.get("/seal-absent", async (event) => {
      await updateSession(event, sessionConfig, { user: "ana" });
      return {};
    });
    t.app.get("/seal-empty", async (event) => {
      await updateSession(event, { ...sessionConfig, extraUnsealPasswords: [] }, { user: "ana" });
      return {};
    });
    for (const path of ["/seal-absent", "/seal-empty"]) {
      const token = tokenOf(sessionCookie(await t.fetch(path)));
      const parts = token.split("*");
      expect(parts).toHaveLength(8);
      expect(parts[0]).toBe("Fe26.2");
      expect(parts[1]).toBe("");
      expect(await unseal(token, password, sealDefaults)).toMatchObject({
        data: { user: "ana" },
      });
    }
  });

  it("seals new sessions with password only", async () => {
    t.app.get("/seal-extra", async (event) => {
      const session = await updateSession(
        event,
        { ...sessionConfig, extraUnsealPasswords: [oldA] },
        { user: "ana" },
      );
      return { id: session.id };
    });
    const res = await t.fetch("/seal-extra");
    const body = await res.json();
    const token = tokenOf(sessionCookie(res));
    expect(await unseal(token, password, sealDefaults)).toMatchObject({
      id: body.id,
      data: { user: "ana" },
    });
    await expect(unseal(token, oldA, sealDefaults)).rejects.toThrow("Bad hmac value");
  });

  it("opens a session sealed with an extra password", async () => {
    readRoute("/read-a", { ...sessionConfig, extraUnsealPasswords: [oldA] });
    const res = await t.fetch("/read-a", {
      headers: { Cookie: `h3-test=${await sealedWith(oldA)}` },
    });
    expect(await res.json()).toMatchObject({ id: "s1", data: { user: "ana" } });
  });

  it("opens a session with any of several extra passwords", async () => {
    readRoute("/read-b", { ...sessionConfig, extraUnsealPasswords: [oldA, oldB] });
    const res = await t.fetch("/read-b", {
      headers: { Cookie: `h3-test=${await sealedWith(oldB)}` },
    });
    expect(await res.json()).toMatchObject({ id: "s1", data: { user: "ana" } });
  });

  it("starts a new session for a cookie sealed with an unknown password", async () => {
    readRoute("/read-x", { ...sessionConfig, extraUnsealPasswords: [oldA] });
    const res = await t.fetch("/read-x", {
      headers: { Cookie: `h3-test=${await sealedWith(unknownX)}` },
    });
    const body = await res.json();
    expect(body.id).not.toBe("s1");
    expect(body.data).toEqual({});
  });

  it("reseals a cookie opened by an extra password with password", async () => {
    readRoute("/reseal", { ...sessionConfig, extraUnsealPasswords: [oldA] });
    const res = await t.fetch("/reseal", {
      headers: { Cookie: `h3-test=${await sealedWith(oldA)}` },
    });
